const orders = $input.all().map(i => i.json);
const totalRevenue = orders.reduce((sum, o) => sum + parseFloat(o.total_price || 0), 0);
const totalOrders = orders.length;
const avgOrderValue = totalOrders > 0 ? (totalRevenue / totalOrders).toFixed(2) : 0;
const newCustomers = orders.filter(o => o.customer?.orders_count === 1).length;
const returningCustomers = totalOrders - newCustomers;

const productCounts = {};
for (const order of orders) {
  for (const item of order.line_items || []) {
    productCounts[item.title] = (productCounts[item.title] || 0) + item.quantity;
  }
}
const topProducts = Object.entries(productCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, qty]) => `${name} (${qty} sold)`);

const weekStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const weekEnd = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

return [{ json: { totalRevenue: totalRevenue.toFixed(2), totalOrders, avgOrderValue, newCustomers, returningCustomers, topProducts, weekStart, weekEnd } }];
